SELECT A.BOOKSET_ID, A.BOOKSET_NAME, A.BOOKSET_TYPE, A.ACCT_MODE, A.ACCT_SUBJECT_ID, A.ACCT_SUBJECT_TYPE, A.STANDARD_CCY, A.BOOKSET_ID_TMPL, A.ACCT_STANDARD, A.START_DATE, A.END_DATE, A.CREATE_USER, A.CREATE_DEPT, A.CREATE_TIME, A.UPDATE_USER, A.UPDATE_TIME
,A.BOK_SPEC_MODE, A.BOOKSET_FULLNAME
FROM BOK_BOOKSET A LEFT JOIN BOK_BOOKSET_DATE B ON A.BOOKSET_ID = B.BOOKSET_ID WHERE A.ACCT_SUBJECT_ID = #{prodId}

mapper.update:
update VAL_INTERF_ACTIONLOG

	STATUS = #{status},
	DETAIL_ACTION = #{detailAction}

		,EXEC_Result = #{execResult}


where STATUS IN

	#{item,jdbcType=CHAR}

mapper.select:
SELECT
B.ACCT_TYPE AS acctType
FROM BOK_BOOKSET A
INNER JOIN BOK_BOOKSET_CAPACCT_INFO B
ON A.BOOKSET_ID = B.BOOKSET_ID
WHERE B.ACCT_NO = #{acctNo}
AND A.ACCT_SUBJECT_ID = #{prodId}

	AND B.CCY = #{ccy}

SELECT
T.TRADE_ID
FROM TRD_PRODUCT_DEAL T
WHERE T.F_TRADE_ID= #{fTradeId}
AND T.PS = #{ps}
AND T.FINPROD_TYPE= #{finprodType}
AND T.FINPROD_ID= #{finprodId}
AND
T.BUSI_TYPE= #{busiType}
AND T.BRANCH= #{branch}
AND T.TRADE_STATUS='01'

SELECT DEAL.TRADE_ID FROM TRD_PRODUCT_DEAL DEAL
WHERE DEAL.FINPROD_ID =#{finprodId}
AND DEAL.FINPROD_TYPE = #{finprodType}
AND DEAL.BUSI_TYPE = #{busiType}
AND DEAL.PS = #{ps}
AND DEAL.F_TRADE_ID = #{fTradeId}
AND DEAL.TRADE_STATUS='01'

SELECT T.CASH_ID AS cashId, T.EFF_DATE AS effDate, T.INT_TYPE AS intType,
T.RATE AS basicRate, T.BENCHMARK_TYPE AS benchmarkType, T.RESET_TYPE AS resetType,
T.Observe_Bef_Day as preObsNum, T.COEFFICIENT AS coefficient, T.SPREAD_RATE AS spreadRate, T.HIGHEST_RATE AS highestRate, T.LOWEST_RATE AS lowestRate, T.BENCHMARK_ID AS benchmarkId, T.BASIS AS basis, T.FINPROD_ID AS finprodId, T.FINPROD_TYPE AS finprodType, T.BRANCH AS branch FROM FIN_RATE_INFO T WHERE (T.CASH_ID,T.EFF_DATE) IN ( SELECT CASH_ID,MAX(EFF_DATE) EFF_DATE FROM FIN_RATE_INFO WHERE EFF_DATE <= #{interfDate} GROUP BY CASH_ID )
AND T.INT_TYPE= #{intType}
AND T.RESET_TYPE= #{resetType}
AND T.PRE_OBS_NUM= #{preObsNum}
AND T.BENCHMARK_TYPE= #{benchmarkType}
AND T.FINPROD_TYPE= #{finprodType}

	SELECT order_id
  FROM (SELECT T.ORDER_ID,row_number() over() ROWNUM
          FROM STL_ORDERS T
         WHERE T.BUSI_TYPE = #{busiType}
           AND T.ORDER_TYPE = #{orderType}

           	  AND T.TRADE_ID = #{tradeId}


           	  AND  AND T.F_ORDER_ID = #{fOrderId} 

           AND T.SETTLE_STATUS = '01'
         ORDER BY T.UPDATE_TIME)
 where rownum  < 2

SELECT
 	BOOKSET_SCHEME_SEQ.nextval as booksetSchemeId,schemeId from (select row_number() over() rownum, 
	T.SCHEME_ID schemeId
FROM BOK_VAL_SCHEME T
WHERE T.ISDEFAULT = #{isdefault}
)where  rownum <2

SELECT PRD.FINPROD_ID as finprodId,PRD.FINPROD_TYPE as finprodType,PRD.branch FROM ( SELECT T.FINPROD_ID, T.FINPROD_TYPE, 0 branch FROM FIN_PRODUCT T WHERE T.FINPROD_TYPE IN ('F16','F26') UNION ALL SELECT A.ACCT_SUBJECT_ID, A.ACCT_SUBJECT_TYPE, 0 as branch FROM BOK_ACCT_SUBJECT_INFO A LEFT JOIN BOK_BOOKSET BOK ON A.ACCT_SUBJECT_ID = BOK.ACCT_SUBJECT_ID AND A.ACCT_SUBJECT_TYPE = BOK.ACCT_SUBJECT_TYPE WHERE A.ACCT_SUBJECT_TYPE IN ('F18','F26') UNION ALL SELECT B.FINPROD_ID, B.FINPROD_TYPE, round(to_char(B.VDATE,'yyyyMMdd')) as branch FROM FIN_TRADE_PRODUCT B WHERE B.FINPROD_TYPE = 'F22' ) PRD WHERE PRD.FINPROD_ID = #{finprodId}
AND PRD.FINPROD_TYPE = #{finprodType }
AND PRD.branch = #{branch }

	SELECT
	  C.BOOKSET_ID AS booksetId, 
	  C.BUSI_ID AS finprodId,
	  C.BUSI_DETAIL_TYPE AS finprodType,
	  C.BRANCH AS branch,
	  D.ACCT_NO AS acctNo
	FROM (
		SELECT C.BOOKSET_ID,C.BUSI_ID,C.BUSI_DETAIL_TYPE,C.BRANCH
        FROM BOK_ACCT_LAYERING_INFO C
        WHERE C.BUSI_DETAIL_TYPE != 'F18'
        AND C.BUSI_ID = #{finprodId} 

        	AND C.BUSI_DETAIL_TYPE = #{finprodType } 

        UNION
        SELECT B.BOOKSET_ID,S.ACCT_SUBJECT_ID,S.ACCT_SUBJECT_TYPE,
        0 AS  BRANCH
        FROM BOK_ACCT_SUBJECT_INFO S
        LEFT JOIN BOK_BOOKSET B ON S.ACCT_SUBJECT_ID = B.ACCT_SUBJECT_ID 
             AND S.ACCT_SUBJECT_TYPE = B.ACCT_SUBJECT_TYPE
        WHERE S.ACCT_SUBJECT_TYPE='F18'
        AND S.ACCT_SUBJECT_ID = #{finprodId} 

        	AND S.ACCT_SUBJECT_TYPE = #{finprodType } 

	) C
	LEFT JOIN BOK_BOOKSET_CAPACCT_INFO D ON C.BOOKSET_ID = D.BOOKSET_ID 
	  AND D.ACCT_TYPE = 'A01' AND D.CCY= #{ccy} 
	WHERE C.BUSI_ID = #{finprodId} 

		AND C.BUSI_DETAIL_TYPE = #{finprodType } 


		AND C.BRANCH =  #{branch }

SELECT * FROM TRD_PRODUCT_DEAL
WHERE TOTLE_TRADE_ID = #{fTradeId}
AND TRADE_STATUS = #{tradeStatus}

SELECT COUNT(1) FROM BOK_SCHEME_INFO
WHERE SCHEME_TYPE = #{schemeType}
AND SCH_ID = #{schId}

