	 WHERE 1=1

	 	 	AND BUSI_ID = #{prodId}
		 	AND BUSI_DETAIL_TYPE = #{prodType}
		 	AND BRANCH = #{branch}


		 	AND BOOKSET_ID = #{booksetIdSon}

