SELECT * FROM TRD_PRODUCT_DEAL D 
WHERE (EXISTS (
	SELECT * FROM BOK_DEAL_ACCOUNTING A WHERE D.TRADE_ID = A.BUSI_NO
	)
	OR EXISTS (
	  SELECT * FROM STL_ORDERS S
	  WHERE EXISTS (
	        SELECT * FROM BOK_DEAL_ACCOUNTING A WHERE S.ORDER_ID = A.BUSI_NO
	  )
	  AND S.TRADE_ID = D.TRADE_ID
	)
)
AND D.TRADE_ID= #{tradeId}
AND D.TRADE_STATUS = #{tradeStatus}
